def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(values, fixed, horizontal):
        result = []
        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            color = values[i]
            start = i
            while i < len(values) and values[i] == color:
                i += 1
            if i - start >= 2:
                result.append((fixed, start, i - 1, color))
        return result

    top = runs(grid[0], 0, True)
    bottom = runs(grid[-1], h - 1, True)
    left = runs([grid[r][0] for r in range(h)], 0, False)
    right = runs([grid[r][-1] for r in range(h)], w - 1, False)

    horizontal_pair = next(((a, b) for a in top for b in bottom
                            if a[3] == b[3] and a[2] - a[1] == b[2] - b[1]), None)
    vertical_pair = next(((a, b) for a in left for b in right
                          if a[3] == b[3] and a[2] - a[1] == b[2] - b[1]), None)
    if horizontal_pair is None and vertical_pair is None:
        return out
    horizontal = horizontal_pair is not None
    bars = horizontal_pair if horizontal else vertical_pair
    edge_cells = set()
    for fixed, start, end, color in bars:
        for i in range(start, end + 1):
            edge_cells.add((fixed, i) if horizontal else (i, fixed))
    dots = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
            if grid[r][c] != bg and (r, c) not in edge_cells]
    if not dots:
        return out
    color = dots[0][2]

    def coordinate(bar, point):
        return point[1] if horizontal else point[0]
    def covers(bar):
        return all(bar[1] <= coordinate(bar, p) <= bar[2] for p in dots)
    a, b = bars
    aligned = a if covers(a) else b
    other = b if aligned is a else a
    if horizontal and aligned[0] == h - 1 and other[1] > aligned[1]:
        projected = {other[2] - (coordinate(aligned, p) - aligned[1]) for p in dots}
    else:
        projected = {other[1] + coordinate(aligned, p) - aligned[1] for p in dots}

    if horizontal:
        # Lines through projected positions cross the grid from one horizontal edge to the other.
        if other[0] == h - 1:
            rows = range(0, h - 1)
        elif len(dots) == 1:
            rows = range(1, h)
        else:
            rows = range(1, h - 1)
        for r in rows:
            for c in projected:
                out[r][c] = color

        if len(dots) == 1:
            r, c, _ = dots[0]
            edge_r = aligned[0]
            step = 1 if edge_r > r else -1
            for rr in range(r + step, edge_r, step):
                out[rr][c] = color
        else:
            corner_r = min(r for r, _, _ in dots) if aligned[0] == 0 else max(r for r, _, _ in dots)
            corner_c = min(c for _, c, _ in dots)
            for r, c, _ in dots:
                step = 1 if corner_r > r else -1
                for rr in range(r, corner_r + step, step):
                    out[rr][c] = color
                step = 1 if corner_c > c else -1
                for cc in range(c, corner_c + step, step):
                    out[corner_r][cc] = color
    else:
        # Each marker connects to its edge segment; corresponding positions cross to the other edge.
        for r, c, _ in dots:
            edge_c = aligned[0]
            step = 1 if edge_c > c else -1
            for cc in range(c + step, edge_c, step):
                out[r][cc] = color
        if other[0] == w - 1:
            columns = range(0, w - 1)
        else:
            columns = range(1, w)
        for c in columns:
            for r in projected:
                out[r][c] = color

    for r, c, _ in dots:
        out[r][c] = 4
    return out

